contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint past) public payable {
        require(address(this).balance >= amount);
        // Setup: drive pastBlockTime via a successful fallback call.
        // To succeed, the call must send 10 ether and have block.timestamp > pastBlockTime.
        // We call it with 10 ether so the setup call succeeds regardless of the provided amount.
        c.fallback{value: 10 ether}();

        uint before = c.pastBlockTime();
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted || c.pastBlockTime() == before);
    }

    receive() external payable {}
    fallback() external payable {}
}

