contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint futureOffset) public payable {
        require(address(this).balance >= 10 ether);

        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // Ensure the upcoming call's timestamp is strictly greater than beforeTime
        // by first exhausting the timestamp via one successful call, then calling again.
        bool firstReverted;
        try address(c).call{value: 10 ether}("") {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // Determine what the stored time is now and what the next call will see.
        uint oneTime = c.pastBlockTime();
        require(!firstReverted);

        bool reverted;
        try address(c).call{value: 10 ether}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        if (!reverted) {
            // A successful call must have advanced pastBlockTime beyond oneTime and kept at least the fresh 10 ether.
            assert(afterTime > oneTime);
            assert(afterBalance >= beforeBalance + 100 ether);
        } else {
            // A revert must have left pastBlockTime exactly at oneTime.
            assert(afterTime == oneTime);
            assert(afterBalance >= beforeBalance + 10 ether);
        }
    }

    receive() external payable {}
}

