        // Send a first 10 ether fallback call, so that the second call has a
        // strictly greater block.timestamp than the stored pastBlockTime.
        c.fallback{value: 10 ether}();

        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        if (!reverted) {
            assert(afterTime == block.timestamp + 1);
            if (block.number % 15 == 0) {
                assert(afterBalance == 0);
                assert(address(this).balance >= 20 ether);
            } else {
                assert(afterBalance == beforeBalance + 10 ether);
