contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint advance) public payable {
        // amount is the ether sent to c's fallback; advance is how far into the future
        // (relative to the current block timestamp) we try to move pastBlockTime.
        require(amount <= address(this).balance);

        uint beforeTime = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Drive the timestamp forward so that block.timestamp > beforeTime is possible.
        // If advance is too large for a valid timestamp, this will revert and the
        // test transaction is discarded; the checker only needs some reachable execution.
        // Using a top-level call to c.fallback with value = amount.
        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule: the fallback succeeds iff it receives exactly 10 ether and
        // block.timestamp is strictly greater than the previous pastBlockTime.
        // On success, pastBlockTime becomes block.timestamp + 1 and c receives exactly 10 ether.
        // On failure, neither pastBlockTime nor c's balance changes from the sending attempt.
        if (amount == 10 ether && block.timestamp > beforeTime) {
            assert(!reverted && afterTime == block.timestamp + 1 && afterBal == beforeBal + 10 ether);
        } else {
            assert(reverted && afterTime == beforeTime && afterBal == beforeBal);
        }
    }

    receive() external payable {}
}

