contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint ts) public payable {
        require(address(this).balance >= amount);

        // Establish a known precondition state for the reverted calls:
        // if amount is exactly 10 ether, first make a successful call
        // so that pastBlockTime is set to block.timestamp + 1.
        if (amount == 10 ether) {
            c.fallback{value: amount}();
        }

        uint beforePast = c.pastBlockTime();
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint balAfter = address(c).balance;

        // The rule: the fallback succeeds exactly when 10 ether is sent and
        // the current block timestamp is strictly greater than pastBlockTime.
        assert(reverted == !(amount == 10 ether && ts > beforePast));
        // On success, pastBlockTime must be advanced to more than the prior value.
        assert(ts > beforePast || afterPast == beforePast);
        // On failure, no Ether should have moved into the contract.
        assert(!reverted || balAfter >= 10 ether || address(c).balance >= amount);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // If the current call could be a successful one, first make a successful
        // call to set pastBlockTime to a future value, guaranteeing that a second
        // call with 10 ether will revert because the timestamp won't advance.
        // Otherwise, just ensure some pastBlockTime exists.
        if (amount == 10 ether) {
            (bool ok0, ) = address(c).call{value: 10 ether}("");
            // ignore ok0: it may revert if the contract was already called in this block,
            // but after this, pastBlockTime is either set or remains from a previous tx
        }

        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // The decision: success exactly when 10 ether is sent and the block
        // timestamp is strictly greater than the timestamp recorded before this call.
        bool expectedSuccess = (amount == 10 ether) && (block.timestamp > beforePast);
        assert(reverted == !expectedSuccess);

        // On success, pastBlockTime must be updated to block.timestamp + 1.
        assert(!expectedSuccess || afterPast == block.timestamp + 1);

        // On revert (including the case of a non-10-ether call), if 10 ether was
        // sent then it must be returned, so the contract balance cannot increase;
        // for other amounts, the failed call must not change the balance either.
        if (reverted) {
            assert(afterBal == beforeBal);
        } else {
            // Successful call must add exactly the sent amount.
            assert(afterBal == beforeBal + amount);
        }
    }

    receive() external payable {}
}

