contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint nextTimestamp) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Step 1: Observe the initial stored timestamp (before any state change).
        uint origPast = c.pastBlockTime();

        // Step 2: If a real block.timestamp control is not possible,
        // we cannot force nextTimestamp; the property uses whatever
        // timestamp the runtime provides.  We still rely on the
        // precondition that the call should succeed only if the EVM
        // timestamp satisfies the > pastBlockTime requirement.
        // Therefore, we use the current block.timestamp as the only
        // observable timestamp for this transaction.
        // We drive exactly one value-transferring fallback call.
        bool reverted;
        uint balBefore = address(c).balance;
        try c { value: amount }() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;
        uint newPast = c.pastBlockTime();

        // General rule:
        // 1) If the call did not revert, it must have sent exactly 10 ether.
        // 2) Timestamp must have advanced: newPast > origPast.
        // 3) If block.number % 15 == 0, the entire balance balBefore + 10 ether
        //    is transferred out, so balAfter == 0 (assuming no other incoming ether),
        //    and otherwise balAfter == balBefore + amount.
        // 4) However, if the call reverts, no state change occurred: newPast == origPast.
        assert(
            reverted
                ? (newPast == origPast && balAfter == balBefore)
                : (newPast == block.timestamp + 1 &&
                   (block.number % 15 == 0
                       ? balAfter == 0
                       : balAfter == balBefore + amount))
        );
    }

    receive() external payable {}
}

