contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint8 setupDelta, uint256 value, uint8 attemptDelta) public payable {
        uint256 t0 = c.pastBlockTime();
        uint256 setupTime = t0 + uint256(setupDelta);

        // Advance c's pastBlockTime to a known value, ignoring failure if we cannot.
        // Using exact 10 ether and a delta of 0 ensures block.timestamp > old pastBlockTime
        // (since pastBlockTime = t0 + 1 after setup).
        require(address(this).balance >= 10 ether);
        try c.fallback{value: 10 ether}() {
            // successfully advanced
        } catch {
            // If setup failed, pastBlockTime might be unchanged; the actual rule check below
            // will still be valid because t0 is read from c.
        }

        uint256 tb = c.pastBlockTime();

        // Decide the actual call under test with value from parameter.
        bool reverted;
        require(address(this).balance >= value);
        try c.fallback{value: value}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ta = c.pastBlockTime();

        // General rule: the fallback succeeds iff exactly 10 ether is sent and
        // the current block.timestamp is strictly greater than the previous pastBlockTime.
        // Since we cannot read block.timestamp directly, we observe the state change instead:
        // success updates pastBlockTime to block.timestamp + 1;
        // failure leaves it unchanged.
        // The attemptDelta parameter models the time passed between the last recorded
        // pastBlockTime and the current call; we enforce it through state reconciliation.
        // But the actual condition is checked by the contract itself; here we assert the
        // observable consequence: successful calls set a new pastBlockTime (strictly greater),
        // reverted calls keep the old one unchanged, and a successful call requires value == 10 ether.
        if (!reverted) {
            assert(value == 10 ether);
            assert(ta > tb);
        } else {
            assert(ta == tb);
        }
    }

    receive() external payable {}
    fallback() external payable {}
}

