contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint64 targetTime) public payable {
        uint beforeBalance = address(c).balance;
        uint beforePast = c.pastBlockTime();

        require(address(this).balance >= 10 ether);
        // Ensure block.timestamp is greater than pastBlockTime by taking a target time
        // that will be at least 1 after the current pastBlockTime. The caller controls
        // the block timestamp indirectly by mining; we enforce the precondition.
        require(uint256(targetTime) > beforePast);

        bool reverted;
        uint pastAfter;
        try c.fallback{value: 10 ether}() {
            reverted = false;
            pastAfter = c.pastBlockTime();
        } catch {
            reverted = true;
        }

        // General rule: with >=10 ether sent and a timestamp strictly greater than
        // the previously stored pastBlockTime, the fallback must succeed (not revert),
        // C's balance must increase by exactly 10 ether, and pastBlockTime must be
        // updated to precisely block.timestamp + 1. Otherwise it must revert.
        assert(
            (!reverted &&
                address(c).balance == beforeBalance + 10 ether &&
                pastAfter == uint256(targetTime) + 1) ||
            (reverted && address(c).balance == beforeBalance)
        );
    }

    receive() external payable {}
}

